final class Point {
    private final int x;
    private final int y;
    Point(int x, int y) { this.x = x; this.y = y; }

    @Override
    public boolean equals(Object o) {
        // Un seul test instanceof avec variable de pattern, puis && sur les champs.
        return false;
    }
}

solution:
@Override
public boolean equals(Object o) {
    return o instanceof Point other && x == other.x && y == other.y;
}
